package com.bank.portal.web; import com.bank.portal.domain.CardStatus; import com.bank.portal.service.BankingService; import com.bank.portal.web.ApiDtos.*; import jakarta.validation.Valid; import java.util.*; import lombok.RequiredArgsConstructor; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/cards") @RequiredArgsConstructor public class CardController {private final BankingService service; @GetMapping @PreAuthorize("hasRole('STAFF')") public List<CardView> all(){return service.allCards();}@GetMapping("/mine") @PreAuthorize("hasRole('CUSTOMER')") public List<CardView> mine(Authentication a){return service.ownCards(a.getName());}@GetMapping("/{id}") public CardView one(@PathVariable Long id,Authentication a){boolean staff=a.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_STAFF"));return service.cardView(id,a.getName(),staff);}@PostMapping @PreAuthorize("hasRole('STAFF')") public CardView issue(@Valid @RequestBody CardRequest r){return service.issue(r);}@PutMapping("/{id}") @PreAuthorize("hasRole('STAFF')") public CardView update(@PathVariable Long id,@Valid @RequestBody CardRequest r){return service.updateCard(id,r);}@PatchMapping("/{id}/status") @PreAuthorize("hasRole('STAFF')") public CardView status(@PathVariable Long id,@RequestParam CardStatus value){return service.staffStatus(id,value);}@PatchMapping("/{id}/block") @PreAuthorize("hasRole('CUSTOMER')") public CardView blockMine(@PathVariable Long id,Authentication a){return service.blockOwn(id,a.getName());}}
